import React, { useRef, useState } from "react";
import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../firebase"; // Import the auth object from your Firebase setup
import "../styles/Login.css";
import Button from "./Button";
import Spinner from "./Spinner";
import { useNavigate } from 'react-router-dom';

function Login() {
  const userRef = useRef<HTMLInputElement | null>(null);
  const pwRef = useRef<HTMLInputElement | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async () => {
    setIsLoading(true);
    setError(null)
    const username = userRef.current?.value || "";
    const pw = pwRef.current?.value || "";
    // const formData = {username, pw}

    try {
      await signInWithEmailAndPassword(auth, username, pw);
    } catch (err) {
      console.log(err);
      setError(
        "Failed to log in. Please check your credentials and try again."
      );
    }
    return;
  };

  return (
    <div className="login">
      <h1>Welcome to MLB Match Maker!</h1>
      <form onSubmit={(e) => e.preventDefault}>
        <label>Username:</label>
        <input type="text" ref={userRef} />
        <label>Password:</label>
        <input type="text" ref={pwRef} />
      </form>
      {error && <div style={{ color: "red" }}>{error}</div>}
      <Button onClick={handleSubmit}>
        {isLoading ? <Spinner size={30} /> : "Submit"}
      </Button>
    </div>
  );
}

export default Login;
